put('service1','rst31-service1-link-infant-current',{'title':'शिशु की विधि नवीनतम आधिकारिक पाठ से देखें','text':'शिशु और वयस्क की विधि अलग है। JRC2025 पर आधारित बाल एवं परिवार एजेंसी के नवीनतम चित्र और आधिकारिक वीडियो का मार्गदर्शन देखें।'},{'title':'শিশুর পদ্ধতি সর্বশেষ সরকারি পাঠে দেখুন','text':'শিশু ও প্রাপ্তবয়স্কের পদ্ধতি আলাদা। JRC2025-ভিত্তিক শিশু ও পরিবার সংস্থার সর্বশেষ চিত্র ও সরকারি ভিডিওর নির্দেশনা দেখুন।'})
